def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find full-width and full-height separator lines.
    hseps = [r for r in range(h) if len(set(grid[r])) == 1]
    vseps = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    vseps = [c for c in vseps if len({grid[r][c] for r in range(h)}) == 1]

    # Keep only lines whose color is consistent across the entire line.
    hseps = [r for r in hseps if len(set(grid[r])) == 1]
    hbounds = [-1] + hseps + [h]
    vbounds = [-1] + vseps + [w]

    tiles = []
    for ri in range(len(hbounds) - 1):
        r0, r1 = hbounds[ri] + 1, hbounds[ri + 1]
        for ci in range(len(vbounds) - 1):
            c0, c1 = vbounds[ci] + 1, vbounds[ci + 1]
            if r0 < r1 and c0 < c1:
                tiles.append((r0, r1, c0, c1))

    # Use the tile with the greatest number of cells unlike the common background.
    colors = {}
    for row in grid:
        for value in row:
            colors[value] = colors.get(value, 0) + 1
    background = max(colors, key=colors.get)

    source = max(
        tiles,
        key=lambda t: sum(
            grid[r][c] != background
            for r in range(t[0], t[1])
            for c in range(t[2], t[3])
        ),
    )
    sr0, sr1, sc0, sc1 = source
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in tiles:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = pattern[r - r0][c - c0]
    return out
